<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from "vue";
import {useI18n} from "vue-i18n";
import {ElMessage} from "element-plus";
import {AppIcon} from "@appnexus/icons";
import {ManagedDialog,ManagementTable,TreeListTemplate,type ManagementColumn} from "@appnexus/ui";
import type {BusinessDictionary,DictionaryItem,DictionaryManagementApi,DictionaryStatus} from "./index";

/** 页面复用左树右表、统一弹窗和 Element Plus；字典类型适合作为右侧数据范围选择器。 */
const props=defineProps<{api:DictionaryManagementApi;errorText:(error:unknown)=>string}>();
const {t}=useI18n();
/** 本人能力失败时保持空集合，不能回退为管理员；真实接口仍逐请求鉴权。 */
const capabilities=ref<string[]>([]);
const can=(action:string)=>capabilities.value.includes(action);
const dictionaries=ref<BusinessDictionary[]>([]),items=ref<DictionaryItem[]>([]),selectedId=ref(""),loading=ref(false),saving=ref(false),error=ref(""),query=ref(""),submitted=ref("");
const dictionaryDialog=ref<"create"|"edit"|"">(""),itemDialog=ref<"create"|"edit"|"">(""),editingItem=ref<DictionaryItem>();
const dictionaryForm=reactive({code:"",name:"",description:"",status:"ENABLED" as DictionaryStatus,sortOrder:100,version:0});
const itemForm=reactive({parentId:null as string|null,code:"",value:"",name:"",description:"",status:"ENABLED" as DictionaryStatus,sortOrder:100,version:0});
const selected=computed(()=>dictionaries.value.find(value=>value.id===selectedId.value));
const filtered=computed(()=>{const word=submitted.value.trim().toLocaleLowerCase();return items.value.filter(item=>!word||[item.code,item.value,item.name,item.description].some(value=>value?.toLocaleLowerCase().includes(word)));});
/** 操作列预留 240px，容纳中英文三个平铺按钮；窄屏由表格内部滚动承载。 */
const columns=computed<ManagementColumn[]>(()=>[{key:"name",prop:"name",label:t("dictionary.name"),minWidth:160},{key:"code",prop:"code",label:t("dictionary.code"),minWidth:130},{key:"value",prop:"value",label:t("dictionary.value"),minWidth:130},{key:"parent",label:t("dictionary.parent"),minWidth:140},{key:"status",label:t("dictionary.status"),width:100},{key:"sortOrder",prop:"sortOrder",label:t("dictionary.sortOrder"),width:100},{key:"operations",label:t("tenant.operation"),width:240,fixed:"right"}]);
const parentOptions=computed(()=>items.value.filter(item=>item.id!==editingItem.value?.id&&!descendants(editingItem.value?.id).has(item.id)));
function descendants(id?:string){const result=new Set<string>();if(!id)return result;const visit=(parent:string)=>items.value.filter(item=>item.parentId===parent).forEach(item=>{result.add(item.id);visit(item.id);});visit(id);return result;}
function parentName(id?:string|null){return items.value.find(item=>item.id===id)?.name||"—";}
async function loadDictionaries(){loading.value=true;error.value="";try{capabilities.value=await props.api.capabilities();dictionaries.value=await props.api.list();if(!dictionaries.value.some(value=>value.id===selectedId.value))selectedId.value=dictionaries.value[0]?.id||"";}catch(cause){capabilities.value=[];error.value=props.errorText(cause);}finally{loading.value=false;}}
async function loadItems(){if(!selectedId.value){items.value=[];return;}loading.value=true;error.value="";try{items.value=await props.api.items(selectedId.value);}catch(cause){error.value=props.errorText(cause);}finally{loading.value=false;}}
watch(selectedId,loadItems);onMounted(loadDictionaries);
function search(reset=false){if(reset)query.value="";submitted.value=query.value;}
function openDictionary(value?:BusinessDictionary){dictionaryDialog.value=value?"edit":"create";Object.assign(dictionaryForm,value?{code:value.code,name:value.name,description:value.description||"",status:value.status,sortOrder:value.sortOrder,version:value.version}:{code:"",name:"",description:"",status:"ENABLED",sortOrder:100,version:0});}
function openItem(value?:DictionaryItem,parentId:string|null=null){editingItem.value=value;itemDialog.value=value?"edit":"create";Object.assign(itemForm,value?{parentId:value.parentId||null,code:value.code,value:value.value,name:value.name,description:value.description||"",status:value.status,sortOrder:value.sortOrder,version:value.version}:{parentId,code:"",value:"",name:"",description:"",status:"ENABLED",sortOrder:100,version:0});}
async function saveDictionary(){saving.value=true;error.value="";try{if(dictionaryDialog.value==="edit"&&selected.value)await props.api.update(selected.value.id,{name:dictionaryForm.name,description:dictionaryForm.description,status:dictionaryForm.status,sortOrder:dictionaryForm.sortOrder,version:dictionaryForm.version});else await props.api.create({code:dictionaryForm.code,name:dictionaryForm.name,description:dictionaryForm.description,sortOrder:dictionaryForm.sortOrder});dictionaryDialog.value="";ElMessage.success(t("dictionary.saved"));await loadDictionaries();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
async function saveItem(){if(!selected.value)return;saving.value=true;error.value="";try{if(itemDialog.value==="edit"&&editingItem.value)await props.api.updateItem(selected.value.id,editingItem.value.id,{parentId:itemForm.parentId,name:itemForm.name,description:itemForm.description,status:itemForm.status,sortOrder:itemForm.sortOrder,version:itemForm.version});else await props.api.createItem(selected.value.id,{parentId:itemForm.parentId,code:itemForm.code,value:itemForm.value,name:itemForm.name,description:itemForm.description,sortOrder:itemForm.sortOrder});itemDialog.value="";ElMessage.success(t("dictionary.saved"));await loadItems();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
async function removeDictionary(){if(!selected.value)return;saving.value=true;try{await props.api.remove(selected.value.id,selected.value.version);ElMessage.success(t("dictionary.deleted"));await loadDictionaries();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
async function removeItem(item:DictionaryItem){saving.value=true;try{await props.api.removeItem(item.dictionaryId,item.id,item.version);ElMessage.success(t("dictionary.deleted"));await loadItems();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
const required=[{required:true,whitespace:true,max:100,message:t("dictionary.required"),trigger:"blur"}],codeRules=[{required:true,pattern:/^[a-z][a-z0-9_]{1,63}$/,message:t("dictionary.invalidCode"),trigger:"blur"}];
</script>
<template><div class="management-page"><TreeListTemplate :title="t('dictionary.title')">
 <template #treeHeader><div class="tree-heading"><strong>{{t('dictionary.types')}}</strong><el-tooltip :content="t('dictionary.createType')"><el-button v-operation="'configuration.dictionary:create'" v-if="can('create')" text :aria-label="t('dictionary.createType')" @click="openDictionary()"><AppIcon name="add" :size="18" /></el-button></el-tooltip></div></template>
 <template #tree><el-menu :default-active="selectedId" @select="selectedId=$event"><el-menu-item v-for="value in dictionaries" :key="value.id" :index="value.id"><span>{{value.name}}</span><el-tag class="ml-auto" size="small" :type="value.status==='ENABLED'?'success':'info'">{{t('dictionary.statuses.'+value.status)}}</el-tag></el-menu-item></el-menu><el-empty v-if="!dictionaries.length" :description="t('dictionary.emptyTypes')" :image-size="56" /></template>
 <template v-if="error&&!dictionaryDialog&&!itemDialog" #feedback><el-alert type="error" :title="error" :closable="false" show-icon><el-button link type="primary" @click="loadDictionaries">{{t('account.retry')}}</el-button></el-alert></template>
 <template #search><div class="management-filter"><div class="management-filter-header"><h2 class="management-filter-title">{{selected?.name||t('dictionary.items')}}</h2><div v-if="selected" class="type-actions"><el-button v-operation="'configuration.dictionary:update'" v-if="can('update')" link @click="openDictionary(selected)">{{t('dictionary.editType')}}</el-button><el-popconfirm v-if="can('delete')" :title="t('dictionary.confirmDeleteType')" @confirm="removeDictionary"><template #reference><el-button v-operation="'configuration.dictionary:delete'" link type="danger">{{t('dictionary.delete')}}</el-button></template></el-popconfirm></div></div><el-form inline @submit.prevent="search()"><el-form-item :label="t('dictionary.itemQuery')"><el-input v-model="query" clearable :placeholder="t('dictionary.queryPlaceholder')" /></el-form-item><div class="management-filter-actions"><el-button type="primary" native-type="submit"><AppIcon name="search" :size="16" />{{t('administration.search')}}</el-button><el-button @click="search(true)">{{t('management.reset')}}</el-button></div></el-form></div></template>
 <template #table><ManagementTable embedded :title="t('dictionary.items')" :total="filtered.length" :columns="columns" :rows="filtered" :loading="loading" :busy="saving" :empty-text="selected?t('dictionary.emptyItems'):t('dictionary.selectType')" @refresh="loadItems"><template #actions><el-button v-operation="'configuration.dictionary:item_create'" v-if="can('item_create')" type="primary" :disabled="!selected" @click="openItem()"><AppIcon name="add" :size="16" />{{t('dictionary.createItem')}}</el-button></template><template #parent="{row}">{{parentName(row.parentId)}}</template><template #status="{row}"><el-tag :type="row.status==='ENABLED'?'success':'info'">{{t('dictionary.statuses.'+row.status)}}</el-tag></template><template #operations="{row}"><div class="dictionary-item-actions"><el-button v-operation="'configuration.dictionary:item_update'" v-if="can('item_update')" link type="primary" @click="openItem(row)">{{t('dictionary.edit')}}</el-button><el-button v-operation="'configuration.dictionary:item_create'" v-if="can('item_create')" link type="primary" @click="openItem(undefined,row.id)">{{t('dictionary.addChild')}}</el-button><el-popconfirm v-if="can('item_delete')" :title="t('dictionary.confirmDeleteItem')" @confirm="removeItem(row)"><template #reference><el-button v-operation="'configuration.dictionary:item_delete'" link type="danger" :disabled="row.referenced">{{t('dictionary.delete')}}</el-button></template></el-popconfirm></div></template></ManagementTable></template>
 </TreeListTemplate>
 <ManagedDialog :model-value="Boolean(dictionaryDialog)" :title="t(dictionaryDialog==='edit'?'dictionary.editType':'dictionary.createType')" width="min(600px, calc(100vw - 32px))" :busy="saving" @update:model-value="value=>{if(!value)dictionaryDialog=''}"><el-alert v-if="error" type="error" :title="error" :closable="false" class="mb-4"/><el-form :model="dictionaryForm" label-position="top" @submit.prevent="saveDictionary"><el-form-item :label="t('dictionary.code')" :rules="codeRules" prop="code"><el-input v-model="dictionaryForm.code" :disabled="dictionaryDialog==='edit'||saving" /></el-form-item><el-form-item :label="t('dictionary.name')" :rules="required" prop="name"><el-input v-model="dictionaryForm.name" /></el-form-item><el-form-item :label="t('dictionary.description')"><el-input v-model="dictionaryForm.description" type="textarea" maxlength="500" /></el-form-item><div class="form-row"><el-form-item :label="t('dictionary.status')"><el-select v-model="dictionaryForm.status" :disabled="dictionaryDialog==='create'"><el-option v-for="status in ['ENABLED','DISABLED']" :key="status" :value="status" :label="t('dictionary.statuses.'+status)" /></el-select></el-form-item><el-form-item :label="t('dictionary.sortOrder')"><el-input-number v-model="dictionaryForm.sortOrder" :min="0" :max="9999" /></el-form-item></div><div class="dialog-actions"><el-button @click="dictionaryDialog=''">{{t('organization.cancel')}}</el-button><el-button v-operation="dictionaryDialog==='create'?'configuration.dictionary:create':'configuration.dictionary:update'" type="primary" native-type="submit" :loading="saving">{{t('organization.save')}}</el-button></div></el-form></ManagedDialog>
 <ManagedDialog :model-value="Boolean(itemDialog)" :title="t(itemDialog==='edit'?'dictionary.editItem':'dictionary.createItem')" width="min(680px, calc(100vw - 32px))" :busy="saving" @update:model-value="value=>{if(!value)itemDialog=''}"><el-alert v-if="error" type="error" :title="error" :closable="false" class="mb-4"/><el-form :model="itemForm" label-position="top" @submit.prevent="saveItem"><div class="form-grid"><el-form-item :label="t('dictionary.parent')"><el-select v-model="itemForm.parentId" clearable><el-option v-for="item in parentOptions" :key="item.id" :value="item.id" :label="item.name+' ('+item.code+')'" /></el-select></el-form-item><el-form-item :label="t('dictionary.sortOrder')"><el-input-number v-model="itemForm.sortOrder" :min="0" :max="9999" /></el-form-item><el-form-item :label="t('dictionary.code')" :rules="codeRules" prop="code"><el-input v-model="itemForm.code" :disabled="itemDialog==='edit'" /></el-form-item><el-form-item :label="t('dictionary.value')" :rules="required" prop="value"><el-input v-model="itemForm.value" :disabled="itemDialog==='edit'" maxlength="100" /></el-form-item><el-form-item :label="t('dictionary.name')" :rules="required" prop="name"><el-input v-model="itemForm.name" /></el-form-item><el-form-item :label="t('dictionary.status')"><el-select v-model="itemForm.status" :disabled="itemDialog==='create'"><el-option v-for="status in ['ENABLED','DISABLED']" :key="status" :value="status" :label="t('dictionary.statuses.'+status)" /></el-select></el-form-item></div><el-form-item :label="t('dictionary.description')"><el-input v-model="itemForm.description" type="textarea" maxlength="500" /></el-form-item><div class="dialog-actions"><el-button @click="itemDialog=''">{{t('organization.cancel')}}</el-button><el-button v-operation="itemDialog==='create'?'configuration.dictionary:item_create':'configuration.dictionary:item_update'" type="primary" native-type="submit" :loading="saving">{{t('organization.save')}}</el-button></div></el-form></ManagedDialog>
</div></template>
<style scoped>
/* 同组操作保持单行并统一间距，避免相邻按钮外边距造成换行。 */
.dictionary-item-actions{display:flex;align-items:center;gap:8px;white-space:nowrap}
.dictionary-item-actions :deep(.el-button){flex-shrink:0;margin-left:0}
.tree-heading,.management-filter-header,.type-actions,.dialog-actions{display:flex;align-items:center}.tree-heading,.management-filter-header{justify-content:space-between;gap:8px}.type-actions,.dialog-actions{gap:8px}.dialog-actions{justify-content:flex-end}.form-row,.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}:deep(.el-menu){border-right:0}:deep(.el-menu-item){height:40px;border-radius:var(--el-border-radius-base)}@media(max-width:600px){.form-row,.form-grid{grid-template-columns:1fr}:deep(.el-button){min-height:44px}}</style>
